(function(root){'use strict';
 function mount(view,c,H){const{n,svg,line,label}=H;let type='multipolar',part='soma';const info=H.readout(c),s=H.diagram(view,'Ветвящиеся отростки нейрона, сома, миелин и органеллы');s.setAttribute('viewBox','0 0 640 350');H.select(c,'Морфология',[['multipolar','Мультиполярный'],['bipolar','Биполярный'],['pseudo','Псевдоуниполярный']],type,v=>{type=v;draw();});const parts={soma:['Сома','Содержит ядро и органеллы; интегрирует входы. Размеры органелл на рисунке увеличены.'],dendrites:['Дендриты','Ветвящиеся отростки принимают входы. Шипики показаны условно: они есть не у всех типов нейронов. У псевдоуниполярного нейрона периферическая и центральная ветви относятся к аксону.'],axon:['Аксон','Начальный сегмент, проводящая часть и терминальные ветви. Миелин показан только на части аксона. Начало ПД часто связано с начальным сегментом.'],nucleus:['Ядро','ДНК и регуляция экспрессии генов; внутри видно ядрышко.'],mitochondria:['Митохондрии','Синтез ATP и другие клеточные процессы. Внутренние складки — кристы.'],ribosomes:['Рибосомы и ЭПС','Рибосомы синтезируют белок. Шероховатая ЭПС и полирибосомы образуют вещество Ниссля, которого нет в аксонном холмике.'],golgi:['Аппарат Гольджи','Модификация и сортировка белков, образование транспортных пузырьков.'],lysosomes:['Лизосомы','Расщепление и переработка клеточных компонентов.']},buttons=[];const choices=n('div',undefined,'neuro-parts');for(const[id,[title]]of Object.entries(parts)){const b=n('button',title,'quiet outlined');b.type='button';b.onclick=()=>{part=id;draw();};choices.append(b);buttons.push([id,b]);}c.append(choices);function draw(){s.replaceChildren();const defs=svg('defs'),gradient=svg('radialGradient',{id:'cell-fill'});gradient.append(svg('stop',{offset:'0%','stop-color':'#f2e9d7'}),svg('stop',{offset:'100%','stop-color':'#b5cbbb'}));defs.append(gradient);s.append(defs);const color=id=>part===id?'#aa5e37':'#527f68';function dendrite(x,y,angle,length,width,depth){const end=[x+Math.cos(angle)*length,y+Math.sin(angle)*length];s.append(svg('path',{d:`M${x},${y} Q${(x+end[0])/2+7},${(y+end[1])/2-5} ${end[0]},${end[1]}`,fill:'none',stroke:color('dendrites'),'stroke-width':width,'stroke-linecap':'round'}));if(type==='multipolar'&&depth===1)for(let k=1;k<4;k++){const t=k/4,px=x+(end[0]-x)*t,py=y+(end[1]-y)*t;line(s,px,py,px+Math.sin(angle)*7,py-Math.cos(angle)*7,color('dendrites'),1.5);}if(depth>0){dendrite(...end,angle-.38,length*.62,width*.55,depth-1);dendrite(...end,angle+.43,length*.65,width*.55,depth-1);}}let cx=245,cy=175;if(type==='pseudo'){cx=240;cy=265;line(s,40,125,555,125,color('axon'),5);s.append(svg('path',{d:'M240 230 Q240 180 267 152 L290 125',fill:'none',stroke:color('axon'),'stroke-width':7}));label(s,30,90,'Периферия');label(s,430,90,'К ЦНС');}else{const angles=type==='bipolar'?[Math.PI]:[-2.65,-1.7,2.55,1.6,Math.PI];for(const a of angles)dendrite(cx+Math.cos(a)*42,cy+Math.sin(a)*37,a,type==='bipolar'?84:61,8,2);s.append(svg('path',{d:`M${cx+42} ${cy-11} Q${cx+70} ${cy+1} ${cx+90} ${cy+3} L535 ${cy+3}`,stroke:color('axon'),'stroke-width':5,fill:'none'}));for(let x=360;x<510;x+=56){s.append(svg('rect',{x,y:cy-11,width:46,height:28,rx:13,fill:'#c9b48d',stroke:'#a38d69'}));for(let j=0;j<4;j++)s.append(svg('path',{d:`M${x+10+j*8} ${cy-8} q6 10 0 22`,stroke:'#b09d79',fill:'none','stroke-width':1}));}for(const dy of[-42,0,42]){s.append(svg('path',{d:`M530 ${cy+3} Q552 ${cy+dy} 590 ${cy+dy}`,stroke:color('axon'),'stroke-width':2,fill:'none'}),svg('circle',{cx:592,cy:cy+dy,r:5,fill:color('axon')}));}label(s,330,cy+65,'Миелин · узлы · окончания');}s.append(svg('path',{d:`M${cx-46} ${cy-8} Q${cx-61} ${cy-49} ${cx-15} ${cy-49} Q${cx+25} ${cy-62} ${cx+50} ${cy-11} Q${cx+69} ${cy+13} ${cx+33} ${cy+40} Q${cx-17} ${cy+63} ${cx-47} ${cy+22} Z`,fill:'url(#cell-fill)',stroke:color('soma'),'stroke-width':3}));s.append(svg('ellipse',{cx:cx-5,cy:cy-2,rx:22,ry:25,fill:'#b9a9bd',stroke:color('nucleus'),'stroke-width':part==='nucleus'?4:1}),svg('circle',{cx:cx-10,cy:cy-7,r:7,fill:'#776681'}));for(const[dx,dy]of[[-32,-23],[30,23]]){s.append(svg('ellipse',{cx:cx+dx,cy:cy+dy,rx:12,ry:6,fill:'#d39a75',stroke:color('mitochondria'),'stroke-width':part==='mitochondria'?3:1}));for(let j=-5;j<7;j+=4)line(s,cx+dx+j,cy+dy-4,cx+dx+j+3,cy+dy+4,'#996b4c',1);}for(let j=0;j<3;j++){s.append(svg('path',{d:`M${cx-35} ${cy+18+j*6} q12 -6 22 1`,fill:'none',stroke:color('ribosomes'),'stroke-width':2}));for(let k=0;k<4;k++)s.append(svg('circle',{cx:cx-33+k*6,cy:cy+18+j*6,r:1.6,fill:color('ribosomes')}));s.append(svg('path',{d:`M${cx+23+j*5} ${cy-31} q16 10 1 21`,fill:'none',stroke:color('golgi'),'stroke-width':2.5}));}s.append(svg('circle',{cx:cx+23,cy:cy+2,r:5,fill:color('lysosomes')}));label(s,20,335,'Морфологическая схема · органеллы увеличены, масштаб условный');info.replaceChildren(n('strong',parts[part][0]),n('p',parts[part][1]));for(const[id,b]of buttons)b.setAttribute('aria-pressed',String(id===part));}draw();NeuroSim.cable(view,c,H);}
 root.NeuroMorph={mount};
})(globalThis);
